using namespace fedspatial;
static bool load(const char*n,Matrix*x){return read_matrix(std::string("sync_gpu/tests/fixtures/sync_gpu/")+n,x);}static void add(Matrix&a,const Matrix&b){for(int i=0;i<a.rows*a.cols;i++)a.a[i]+=b.a[i];}static Matrix halve(Matrix a){for(double&v:a.a)v*=.5;return a;}
#define half halve
static GammaLocalSummary cpu_gamma(const WorkerInput&w,const Matrix&k,const GlobalParameters&p){auto q=make_local_p(w.sites,k,w.z,w.x,p.gamma,p.delta,p.alpha,p.range);Matrix rhs=subtract(w.z,matmul(q.B,p.mu));Matrix invrhs=solve_spd(q.M,rhs),invx=solve_spd(q.M,w.x);return {matmul(transpose(w.x),invrhs),matmul(transpose(w.x),invx)};}
int main(){constexpr int n=3,m=2;Matrix k(m,2),s0(n,2),s1(n,2),z0(n,1),z1(n,1),x(n,1),g(1,1),mu(m,1),sig(m,m);double a0[]={0,0,1,.2,.3,1.1},a1[]={1.2,.9,1.8,.1,.4,1.7},ak[]={0,0,1.5,1.5},v0[]={1.2,-.4,.7},v1[]={.1,1.3,-.8},vx[]={1,1,1};std::copy(a0,a0+6,s0.a.begin());std::copy(a1,a1+6,s1.a.begin());std::copy(ak,ak+4,k.a.begin());std::copy(v0,v0+3,z0.a.begin());std::copy(v1,v1+3,z1.a.begin());std::copy(vx,vx+3,x.a.begin());g(0,0)=.15;mu(0,0)=.2;mu(1,0)=-.1;sig(0,0)=.7;sig(0,1)=sig(1,0)=.05;sig(1,1)=.4;GlobalParameters p{g,mu,sig,1.7,1.2,.8};WorkerInput w0{s0,z0,x},w1{s1,z1,x};GpuContext c(0);auto gpu0=compute_gamma_local(c,w0,k,p);auto cpu0=cpu_gamma(w0,k,p);Matrix flg,flx,fg,fx,fo;if(!load("GAMMA_LOCAL_GAMMA.txt",&flg)||!load("GAMMA_LOCAL_XX.txt",&flx)||!load("GAMMA_GLOBAL_GAMMA.txt",&fg)||!load("GAMMA_GLOBAL_XX.txt",&fx)||!load("GAMMA_OUT.txt",&fo))return 2;double local_err=max_abs_diff(gpu0.gamma,flg),xx_err=max_abs_diff(gpu0.xx,flx),cpu_gamma_err=max_abs_diff(gpu0.gamma,cpu0.gamma),cpu_xx_err=max_abs_diff(gpu0.xx,cpu0.xx),out_cpu=max_abs_diff(solve_spd(cpu0.xx,cpu0.gamma),solve_spd(gpu0.xx,gpu0.gamma)),out_py=max_abs_diff(solve_spd(gpu0.xx,gpu0.gamma),fo);bool one=local_err<=1e-10&&xx_err<=1e-10&&cpu_gamma_err<=1e-10&&cpu_xx_err<=1e-10&&out_py<=1e-10;std::cout<<"GAMMA_LOCAL_MAX_ABS_ERROR="<<local_err<<"\nGAMMA_LOCAL_XX_MAX_ABS_ERROR="<<xx_err<<"\nGPU_CPU_GAMMA_LOCAL_MAX_ABS_ERROR="<<cpu_gamma_err<<"\nGPU_CPU_GAMMA_XX_MAX_ABS_ERROR="<<cpu_xx_err<<"\nGPU_CPU_GAMMA_MAX_ABS_ERROR="<<out_cpu<<"\nGPU_PYTHON_GAMMA_MAX_ABS_ERROR="<<out_py<<"\nGAMMA_BLOCK_PARITY="<<(one?"PASS":"FAIL")<<"\n";if(!one)return 1;auto gpu1=compute_gamma_local(c,w1,k,p);Matrix f0g,f0x,f1g,f1x,tg,tx,to;if(!load("TWO_WORKER0_GAMMA_LOCAL_GAMMA.txt",&f0g)||!load("TWO_WORKER0_GAMMA_LOCAL_XX.txt",&f0x)||!load("TWO_WORKER1_GAMMA_LOCAL_GAMMA.txt",&f1g)||!load("TWO_WORKER1_GAMMA_LOCAL_XX.txt",&f1x)||!load("TWO_WORKER_GAMMA_GLOBAL_GAMMA.txt",&tg)||!load("TWO_WORKER_GAMMA_GLOBAL_XX.txt",&tx)||!load("TWO_WORKER_GAMMA_OUT.txt",&to))return 2;double e0=std::max(max_abs_diff(gpu0.gamma,f0g),max_abs_diff(gpu0.xx,f0x)),e1=std::max(max_abs_diff(gpu1.gamma,f1g),max_abs_diff(gpu1.xx,f1x));Matrix ag=half(gpu0.gamma),ax=half(gpu0.xx);add(ag,half(gpu1.gamma));add(ax,half(gpu1.xx));double eg=std::max(max_abs_diff(ag,tg),max_abs_diff(ax,tx)),eo=max_abs_diff(solve_spd(ax,ag),to);bool two=e0<=1e-10&&e1<=1e-10&&eg<=1e-10&&eo<=1e-10;std::cout<<"TWO_WORKER0_GAMMA_LOCAL_MAX_ABS_ERROR="<<e0<<"\nTWO_WORKER1_GAMMA_LOCAL_MAX_ABS_ERROR="<<e1<<"\nTWO_WORKER_GAMMA_GLOBAL_MAX_ABS_ERROR="<<eg<<"\nTWO_WORKER_GAMMA_OUT_MAX_ABS_ERROR="<<eo<<"\nTWO_WORKER_GAMMA_PARITY="<<(two?"PASS":"FAIL")<<"\n";return two?0:1;}
